39: export function useFocusTrap(
40:   isOpen: boolean,
41:   containerRef: RefObject<HTMLElement | null>,
42:   onClose: () => void,
43:   initialFocusRef?: RefObject<HTMLElement | null>,
44:   triggerRef?: RefObject<HTMLElement | null>,
45: ): void {
