51:     if (!isOpen) {
52:       return undefined;
53:     }
54:     savedTriggerRef.current =
55:       triggerRef?.current ?? (document.activeElement instanceof HTMLElement ? document.activeElement : null);
56: 
57:     const container = containerRef.current;
